<?php
declare(strict_types=1);
function activityNames():array{return ['order.created'=>'Narudžba je zaprimljena','order.status'=>'Promijenjen je status narudžbe','order.delivery_prepared'=>'Pripremljena je dostava','order.shipment_updated'=>'Dopunjeni su podaci pošiljke','payment.paid'=>'Evidentirana je naplata','payment.refunded'=>'Evidentiran je povrat novca','stock.adjusted'=>'Evidentiran je ulaz robe','stock_exit.created'=>'Evidentiran je izlaz robe','stock_exit.paid'=>'Naplaćena je lična prodaja','stock_exit.refunded'=>'Vraćen je novac za ličnu prodaju','stock_exit.reversed'=>'Storniran je izlaz robe','product.saved'=>'Sačuvan je artikal','category.saved'=>'Sačuvana je kategorija','delivery.saved'=>'Sačuvan je način dostave','delivery.deleted'=>'Obrisan je način dostave','settings.saved'=>'Sačuvane su postavke','role.saved'=>'Sačuvana je uloga','user.saved'=>'Sačuvan je korisnički račun','mail.test_queued'=>'Pripremljen je probni mail','mail.settings_saved'=>'Sačuvane su mail postavke','mail.retry'=>'Ponovljeno je slanje maila','mail.cancelled'=>'Obustavljeno je slanje maila','store_theme.changed'=>'Promijenjena je tema prodavnice','branding.saved'=>'Sačuvani su logo i brend','theme.changed'=>'Promijenjena je tema administracije','backup.recovered'=>'Završen je oporavak nakon prekida','backup.verified'=>'Provjerena je sigurnosna kopija','backup.created'=>'Napravljena je sigurnosna kopija','backup.imported'=>'Učitana je sigurnosna kopija','backup.downloaded'=>'Preuzeta je sigurnosna kopija','backup.key_downloaded'=>'Preuzet je ključ oporavka','backup.restored'=>'Vraćeni su podaci iz sigurnosne kopije','backup.settings_saved'=>'Sačuvan je raspored sigurnosnih kopija'];}
function activityLabel(string $action):string{return activityNames()[$action]??'Evidentirana je sistemska aktivnost';}
function activityDetails(array $row):string {
    $details=(string)$row['details'];if($row['action']==='backup.restored')$details=preg_replace('/; oporavak [a-f0-9]{32}$/','',$details)??$details;$id=$row['entity_id']??null;$action=$row['action'];$parts=[];
    if($id!==null)$parts[]=match(true){str_starts_with($action,'order.'),str_starts_with($action,'payment.')=>'Narudžba #'.$id,str_starts_with($action,'stock_exit.')=>'Izlaz robe #'.$id,$action==='stock.adjusted',$action==='product.saved'=>'Artikal #'.$id,str_starts_with($action,'mail.')=>'Poruka #'.$id,default=>'Zapis #'.$id};
    if($action==='stock.adjusted'&&preg_match('/^(-?\d+)\s*(.*)$/s',$details,$quantity))return implode(' · ',array_merge($parts,['Količina: '.$quantity[1].' kom.','Obrazloženje: '.($quantity[2]?:'Nije navedeno')]));
    $json=json_decode($details,true);
    if(is_array($json)&&in_array($action,['order.delivery_prepared','delivery.saved'],true)){
        $labels=['method'=>'Način dostave','courier'=>'Kurir','cost'=>'Trošak KM','payer'=>'Dostavu plaća','terms'=>'Uslovi','tracking'=>'Broj pošiljke','note'=>'Obrazloženje','name'=>'Naziv','active'=>'Dostupno kupcima'];
        foreach($json as $key=>$value){if(!isset($labels[$key])||!is_scalar($value))continue;if($key==='payer')$value=($value==='customer'?'kupac':($value==='sender'?'prodavac':$value));if($key==='active')$value=$value?'Da':'Ne';if($value!=='')$parts[]=$labels[$key].': '.$value;}
    }else{
        if($action==='order.status')$details=preg_replace_callback('/\b(new|preparing|shipped|delivered|completed|cancelled|returned|handed_over)\b/',static fn($m)=>orderStatus($m[1]),$details)??$details;
        if($action==='stock_exit.created')foreach(exitReasons() as $key=>$label)$details=preg_replace('/\b'.preg_quote($key,'/').'\b/',$label,$details)??$details;
        if(trim($details)!=='')$parts[]=str_replace(' -> ',' → ',$details);
    }
    return implode(' · ',$parts)?:'Promjena je uredno evidentirana.';
}
function adminThemes():array{return ['emerald'=>['Smaragdna','Zelena navigacija i svijetli radni prostor','#07553b','#f4f7f5'],'navy'=>['Mornarska','Tamnoplava navigacija i tirkizni naglasci','#17344c','#f3f6fa'],'light'=>['Svijetla','Bijela navigacija i mirni zeleni detalji','#edf3ee','#ffffff'],'plum'=>['Šljiva','Ljubičasta navigacija i nježni naglasci','#483050','#faf6fb'],'dark'=>['Tamna','Tamna pozadina za ugodniji večernji rad','#14201e','#202d2a']];}
function adminTheme():string{$theme=setting('admin_theme','emerald');return isset(adminThemes()[$theme])?$theme:'emerald';}
function storeThemes():array{return ['classic'=>['Zelena klasika','Postojeći izgled i vaša odabrana boja naglasaka','#465338','#f5f3e9'],'ocean'=>['Plavi horizont','Tamnoplavo zaglavlje, ledenoplava naslovnica i zaobljene kartice','#173c61','#eaf3fa'],'sand'=>['Topli pijesak','Topli smeđi detalji i kremasta naslovnica','#66513f','#faf0df'],'plum'=>['Ljubičasti studio','Ljubičasto zaglavlje i nježne pastelne površine','#4c335d','#f5edf8'],'minimal'=>['Bijeli minimalizam','Svijetlo zaglavlje, čiste linije i ravnije kartice','#e8ecef','#ffffff']];}
function storeTheme():string{$theme=setting('store_theme','classic');return isset(storeThemes()[$theme])?$theme:'classic';}
